import builtins, time
from nuka.editor.app import ActionError
def frames(n):
    for _ in range(n):
        app.update(True)
def tick():
    return app.actions.run('timeline.status')['tick']
def until_tick(n):
    deadline = time.monotonic() + 60.0
    while tick() != n:
        assert time.monotonic() < deadline, (tick(), n)
        app.update(True)
    frames(3)
def step(n):
    t = tick()
    app.actions.run('sim.step', steps=n)
    until_tick(t + n)
def fails(action, text, **args):
    try:
        app.actions.run(action, **args)
    except ActionError as e:
        assert text in str(e), (action, args, str(e))
    else:
        raise AssertionError((action, args))
def damping(value):
    joints = app.actions.run('robot.joints')['joints']
    ops = [{'target': j['path'], 'field': 'joint.damping', 'after': value} for j in joints]
    app.actions.run('edit.apply', label='Damping', ops=ops)
    frames(4)
    return {j['name']: j['damping'] for j in app.actions.run('robot.joints')['joints']}
def finish(seconds):
    deadline = time.monotonic() + seconds
    while True:
        s = app.actions.run('sysid.status')
        if not s['running']:
            return s
        assert time.monotonic() < deadline, {k: v for k, v in s.items() if k != 'curve'}
        app.update(True)
builtins.si_frames, builtins.si_step, builtins.si_fails = frames, step, fails
builtins.si_damping, builtins.si_finish, builtins.si_until_tick = damping, finish, until_tick
fails('sysid.run', '', params=[{'param': 'joint_damping'}])
d = damping(0.8)
assert all(abs(v - 0.8) < 1e-6 for v in d.values()) and len(d) == 3, d
